<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php';
if($_SESSION['user']['role']!=='admin'){http_response_code(403);die('Access denied');}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO expenses(expense_date,category,description,amount,user_id) VALUES(?,?,?,?,?)');$s->execute([$_POST['expense_date'],trim($_POST['category']),trim($_POST['description']),$_POST['amount'],$_SESSION['user']['id']]);$msg='Expense imehifadhiwa.';}
$rows=$pdo->query('SELECT e.*,u.full_name FROM expenses e JOIN users u ON u.id=e.user_id ORDER BY e.expense_date DESC,e.id DESC LIMIT 100')->fetchAll();?><h2>Expenses</h2><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="card"><form method="post" class="grid"><div><label>Tarehe</label><input type="date" name="expense_date" value="<?=date('Y-m-d')?>" required></div><div><label>Category</label><input name="category" placeholder="Umeme, Chakula, Mshahara" required></div><div><label>Description</label><input name="description" required></div><div><label>Amount</label><input type="number" step="0.01" min="0" name="amount" required></div><div><label>&nbsp;</label><button class="green">+ Hifadhi Expense</button></div></form></div><br><div class="card"><table><tr><th>Tarehe</th><th>Category</th><th>Description</th><th>Amount</th><th>Aliyeingiza</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><?=e($r['category'])?></td><td><?=e($r['description'])?></td><td>TSh <?=number_format($r['amount'])?></td><td><?=e($r['full_name'])?></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/../config/footer.php';?>
